  here_login_desc: { en: "It sits under the QR code. Pick your country, enter your number and tap OK.", tr: "QR kodun altındadır. Ülkenizi seçin, numaranızı girin ve Tamam'a dokunun.", de: "Er steht unter dem QR-Code. Wählen Sie Ihr Land, geben Sie Ihre Nummer ein und tippen Sie auf OK.", id: "Ada di bawah kode QR. Pilih negara Anda, masukkan nomor, lalu ketuk OK.", es: "Está debajo del código QR. Elige tu país, escribe tu número y toca OK.", pt: "Fica abaixo do código QR. Escolha seu país, digite seu número e toque em OK.", ar: "يوجد أسفل رمز QR. اختر بلدك وأدخل رقمك ثم اضغط على OK.", fr: "Il se trouve sous le code QR. Choisissez votre pays, saisissez votre numéro et touchez OK.", ms: "Ia berada di bawah kod QR. Pilih negara anda, masukkan nombor dan ketik OK.", af: "Dit is onder die QR-kode. Kies jou land, tik jou nommer in en tik OK.", hi: "यह QR कोड के नीचे है। अपना देश चुनें, नंबर डालें और OK पर टैप करें।" },
  here_code_title: { en: "Enter the code in WhatsApp", tr: "Kodu WhatsApp'a girin", de: "Geben Sie den Code in WhatsApp ein", id: "Masukkan kode di WhatsApp", es: "Introduce el código en WhatsApp", pt: "Digite o código no WhatsApp", ar: "أدخل الرمز في واتساب", fr: "Entrez le code dans WhatsApp", ms: "Masukkan kod dalam WhatsApp", af: "Voer die kode in WhatsApp in", hi: "कोड WhatsApp में डालें" },
  here_code_desc: { en: "WhatsApp asks for a code. Type in the code shown on the screen.", tr: "WhatsApp bir kod ister. Ekranda görünen kodu yazın.", de: "WhatsApp fragt nach einem Code. Geben Sie den Code ein, der auf dem Bildschirm steht.", id: "WhatsApp meminta kode. Ketik kode yang muncul di layar.", es: "WhatsApp pide un código. Escribe el código que aparece en la pantalla.", pt: "O WhatsApp pede um código. Digite o código que aparece na tela.", ar: "سيطلب واتساب رمزًا. أدخل الرمز الظاهر على الشاشة.", fr: "WhatsApp demande un code. Saisissez le code affiché à l'écran.", ms: "WhatsApp meminta kod. Taip kod yang dipaparkan pada skrin.", af: "WhatsApp vra vir 'n kode. Tik die kode in wat op die skerm wys.", hi: "WhatsApp एक कोड मांगेगा। स्क्रीन पर दिख रहा कोड डालें।" },
  wait_title: { en: "Wait a few seconds", tr: "Birkaç saniye bekleyin", de: "Warten Sie ein paar Sekunden", id: "Tunggu beberapa detik", es: "Espera unos segundos", pt: "Aguarde alguns segundos", ar: "انتظر بضع ثوانٍ", fr: "Patientez quelques secondes", ms: "Tunggu beberapa saat", af: "Wag 'n paar sekondes", hi: "कुछ सेकंड प्रतीक्षा करें" },
  wait_desc: { en: "Your chats load by themselves. Keep the app open until they do.", tr: "Sohbetleriniz kendiliğinden yüklenir. Yüklenene kadar uygulamayı açık tutun.", de: "Ihre Chats werden von selbst geladen. Lassen Sie die App so lange geöffnet.", id: "Obrolan Anda dimuat dengan sendirinya. Biarkan aplikasi terbuka sampai selesai.", es: "Tus chats se cargan solos. Mantén la app abierta hasta que terminen.", pt: "Suas conversas carregam sozinhas. Mantenha o app aberto até terminar.", ar: "ستُحمَّل محادثاتك تلقائيًا. أبقِ التطبيق مفتوحًا حتى تنتهي.", fr: "Vos discussions se chargent toutes seules. Gardez l'application ouverte jusqu'à la fin.", ms: "Perbualan anda dimuatkan dengan sendirinya. Biarkan aplikasi terbuka sehingga selesai.", af: "Jou geselse laai vanself. Hou die app oop totdat hulle klaar is.", hi: "आपकी चैट अपने आप लोड हो जाती हैं। तब तक ऐप खुला रखें।" },
  other_open_title: { en: "Open WhatsApp on the other phone", tr: "Diğer telefonda WhatsApp'ı açın", de: "Öffnen Sie WhatsApp auf dem anderen Telefon", id: "Buka WhatsApp di ponsel yang satunya", es: "Abre WhatsApp en el otro teléfono", pt: "Abra o WhatsApp no outro telefone", ar: "افتح واتساب على الهاتف الآخر", fr: "Ouvrez WhatsApp sur l'autre téléphone", ms: "Buka WhatsApp pada telefon yang satu lagi", af: "Maak WhatsApp op die ander foon oop", hi: "दूसरे फ़ोन में WhatsApp खोलें" },
  other_open_desc: { en: "Open Settings › Linked Devices and tap “Link a Device”.", tr: "Ayarlar › Bağlı Cihazlar'ı açın ve “Cihaz Bağla”ya dokunun.", de: "Öffnen Sie Einstellungen › Verknüpfte Geräte und tippen Sie auf „Gerät verknüpfen“.", id: "Buka Setelan › Perangkat Tertaut, lalu ketuk “Tautkan Perangkat”.", es: "Abre Ajustes › Dispositivos vinculados y toca “Vincular un dispositivo”.", pt: "Abra Configurações › Aparelhos conectados e toque em “Conectar um aparelho”.", ar: "افتح الإعدادات › الأجهزة المرتبطة واضغط على «ربط جهاز».", fr: "Ouvrez Réglages › Appareils connectés et touchez « Associer un appareil ».", ms: "Buka Tetapan › Peranti Terpaut dan ketik “Pautkan Peranti”.", af: "Maak Instellings › Gekoppelde toestelle oop en tik “Koppel 'n toestel”.", hi: "सेटिंग्स › लिंक्ड डिवाइस खोलें और “डिवाइस लिंक करें” पर टैप करें।" },
  other_scan_title: { en: "Scan the QR code", tr: "QR kodunu tarayın", de: "QR-Code scannen", id: "Pindai kode QR", es: "Escanea el código QR", pt: "Escaneie o código QR", ar: "امسح رمز QR", fr: "Scannez le code QR", ms: "Imbas kod QR", af: "Skandeer die QR-kode", hi: "QR कोड स्कैन करें" },
  other_scan_desc: { en: "Point that phone at the QR code shown on this screen.", tr: "O telefonu bu ekrandaki QR koduna doğrultun.", de: "Richten Sie dieses Telefon auf den QR-Code auf diesem Bildschirm.", id: "Arahkan ponsel itu ke kode QR di layar ini.", es: "Apunta ese teléfono al código QR de esta pantalla.", pt: "Aponte aquele telefone para o código QR desta tela.", ar: "وجّه ذلك الهاتف نحو رمز QR الظاهر على هذه الشاشة.", fr: "Dirigez cet autre téléphone vers le code QR affiché à l'écran.", ms: "Halakan telefon itu ke kod QR pada skrin ini.", af: "Rig daardie foon op die QR-kode op hierdie skerm.", hi: "उस फ़ोन को इस स्क्रीन पर दिख रहे QR कोड की ओर रखें।" },
